class _AdmissionStore:
    """Observe the exact successful reservation CAS for ticket accounting.

    LazyTools does not expose a post-CAS approval-purchase hook. Capturing
    the winning input keeps the autonomous comparison on the same snapshot,
    even if another admission lands before this caller spends its ticket.
    """

    def __init__(self, store: Store, key: str):
        self.store = store
        self.key = key
        self.before: dict = {}

    def __getattr__(self, name: str):
        return getattr(self.store, name)

    def compare_and_swap(self, key: str, expected: object, value: object) -> bool:
        won = self.store.compare_and_swap(key, expected, value)
        if won and key == self.key:
            self.before = expected if isinstance(expected, dict) else {}
        return won

cost__parse_timestamp:
def _parse_timestamp(value: Any) -> datetime | None:
    if isinstance(value, datetime):
        parsed = value
    elif isinstance(value, str):
        try:
            parsed = datetime.fromisoformat(value)
        except ValueError:
            return None
    else:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=UTC)
    return parsed.astimezone(UTC)

cost__cost:
def _cost(value: Any) -> float:
    """A finite JSON number, or zero for missing/legacy/malformed values."""
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return 0.0
    parsed = float(value)
    return parsed if math.isfinite(parsed) else 0.0

cost__totals:
def _totals(records: list[dict[str, Any]], *, now: datetime, timestamp_fields: tuple[str, ...]) -> dict[str, float]:
    today_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
    seven_day_start = now - timedelta(days=7)
    today = 0.0
    seven_days = 0.0
    for record in records:
        timestamp = next(
            (parsed for field in timestamp_fields if (parsed := _parse_timestamp(record.get(field))) is not None),
            None,
        )
        if timestamp is None or timestamp > now:
            continue
        cost = _cost(record.get("cost_usd"))
        if timestamp >= seven_day_start:
            seven_days += cost
        if timestamp >= today_start:
            today += cost
    return {"today_usd": today, "last_7_days_usd": seven_days}

cost__sum_totals:
def _sum_totals(*totals: dict[str, float]) -> dict[str, float]:
    """Add corresponding ``today_usd``/``last_7_days_usd`` fields across
    record FAMILIES (e.g. this agent's own turn costs plus the jobs it
    delegated) that must both count toward the same line's total."""
    return {
        "today_usd": sum(t["today_usd"] for t in totals),
        "last_7_days_usd": sum(t["last_7_days_usd"] for t in totals),
    }

cost__unmeasured_cost_counts:
def _unmeasured_cost_counts(
    records: list[dict[str, Any]], *, now: datetime, timestamp_fields: tuple[str, ...]
) -> dict[str, int]:
    today_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
    seven_day_start = now - timedelta(days=7)
    today = 0
    seven_days = 0
    for record in records:
        if not _is_unmeasured(record):
            continue
        timestamp = next(
            (parsed for field in timestamp_fields if (parsed := _parse_timestamp(record.get(field))) is not None),
            None,
        )
        if timestamp is None or timestamp > now:
            continue
        if timestamp >= seven_day_start:
            seven_days += 1
        if timestamp >= today_start:
            today += 1
    return {"today": today, "last_7_days": seven_days}

cost__sum_counts:
def _sum_counts(*counts: dict[str, int]) -> dict[str, int]:
    return {
        "today": sum(c["today"] for c in counts),
        "last_7_days": sum(c["last_7_days"] for c in counts),
    }
